{"hypotheses":[
  {
    "root_cause":"ForecastPipelineSlow: queuing/saturation inside forecast-pipeline",
    "mechanism":"Request concurrency exceeded the available worker/compute capacity, causing forecast jobs to wait in queue before execution.",
    "statement":"The p95 duration is driven by queuing latency inside the forecast-pipeline rather than by individual job execution time."
  },
  {
    "root_cause":"ForecastPipelineSlow: slow upstream input dependency",
    "mechanism":"An upstream data/input service feeding the forecast-pipeline became slow or started timing out, causing forecast jobs to block on I/O.",
    "statement":"Forecast pipeline latency is inflated by slow responses from a required upstream dependency."
  },
  {
    "root_cause":"ForecastPipelineSlow: slow history/feature database queries",
    "mechanism":"Historical data or feature queries became slower or exhausted their connection pool, delaying data retrieval for each forecast run.",
    "statement":"Forecast jobs spend excessive time waiting on history/feature reads from the database."
  },
  {
    "root_cause":"ForecastPipelineSlow: regression or heavier compute path in forecast-pipeline",
    "mechanism":"A recent deployment or configuration change introduced a regression or a more expensive model computation path.",
    "statement":"The forecast computation itself became slower after a code or configuration change."
  }
]}
